{

    internal InnerReplicatorS3Factory S3Factory { get; set; }

    internal InnerReplicatorFirehoseFactory FirehoseFactory { get; set; }

    internal InnerReplicatorCloudWatchLogsFactory CloudWatchLogsFactory { get; set; }

    protected override Humidifier.MSK.ReplicatorTypes.ReplicatorLogDelivery Create()
    {
        var replicatorLogDeliveryResult = CreateReplicatorLogDelivery();
        factoryAction?.Invoke(replicatorLogDeliveryResult);

        return replicatorLogDeliveryResult;
    }

    private Humidifier.MSK.ReplicatorTypes.ReplicatorLogDelivery CreateReplicatorLogDelivery()
    {
        var replicatorLogDeliveryResult = new Humidifier.MSK.ReplicatorTypes.ReplicatorLogDelivery();

        return replicatorLogDeliveryResult;
    }
    public override void CreateChildren(Humidifier.MSK.ReplicatorTypes.ReplicatorLogDelivery result)
    {
        base.CreateChildren(result);

        result.S3 ??= S3Factory?.Build();
        result.Firehose ??= FirehoseFactory?.Build();
        result.CloudWatchLogs ??= CloudWatchLogsFactory?.Build();
    }

} // End Of Class

